mapper.update:
update ${table}
set state = 3,
    msg = #{msg},
    platform = #{platform},
    scan_ip = #{scanIp},
    scan_ua = #{scanUa}
where ticket = #{ticket}

update ${table}
set state = 2,
    login_token = #{loginToken},
    confirm_time = #{confirmTime}
where ticket = #{ticket}

update ${table}
set state = 5,
    login_token = null,
    used_time = #{usedTime}
where ticket = #{ticket} and state = 2 and login_token = #{loginToken}

update ${table}
set state = 4,
    msg = '二维码已刷新作废，请使用最新二维码扫码'
where ticket = #{ticket}
